import 'dart:convert';

import '../models/level.dart';
import 'generated_levels.dart';

/// Puzzles generated by tools/generate_levels.py. Missing levels are errors,
/// never silently substituted with a different puzzle.
abstract final class LevelBook {
  static final Map<int, Level> _levels = _readLevels();

  static Map<int, Level> _readLevels() {
    final data = jsonDecode(generatedLevelsJson) as Map<String, dynamic>;
    final result = <int, Level>{};
    for (final entry in data['levels'] as List<dynamic>) {
      final item = entry as Map<String, dynamic>;
      final words = <PlacedWord>[];
      for (final raw in item['words'] as List<dynamic>) {
        final w = raw as Map<String, dynamic>;
        final word = w['word'] as String;
        final row = w['row'] as int;
        final col = w['col'] as int;
        final down = w['dir'] == 'down';
        words.add(PlacedWord(word, [
          for (var i = 0; i < word.length; i++)
            GridCell(row + (down ? i : 0), col + (down ? 0 : i)),
        ]));
      }
      final number = item['number'] as int;
      if (result.containsKey(number)) throw FormatException('Duplicate level $number');
      result[number] = Level(
        number: number,
        chapter: item['chapter'] as String,
        letters: List<String>.from(item['letters'] as List),
        words: words,
        bonusWords: List<String>.from(item['bonusWords'] as List),
        rows: item['rows'] as int,
        cols: item['cols'] as int,
      );
    }
    return result;
  }

  static Level level(int number) => _levels[number] ??
      (throw RangeError('Level $number is not available'));
  static int levelCount(int number) => _levels.length;
  static List<Level> get all => _levels.values.toList()..sort((a, b) => a.number.compareTo(b.number));
  static int? nextLevelAfter(int number) => _levels.containsKey(number + 1) ? number + 1 : null;
}
